import itertools
import random
import json
from problems import ThreeSat, VertexCover
from reduce import reduce


def three_sat_bruteforce(instance):
    m = instance["num_vars"]
    clauses = instance["clauses"]
    # assignments as tuple of booleans length m (index 0 for var1)
    for bits in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            clause_ok = False
            for lit in clause:
                var = abs(lit) - 1
                val = bits[var]
                if lit > 0 and val:
                    clause_ok = True
                if lit < 0 and not val:
                    clause_ok = True
                if clause_ok:
                    break
            if not clause_ok:
                ok = False
                break
        if ok:
            return True
    return False


def vertex_cover_bruteforce(instance):
    n = instance["n"]
    edges = [tuple(e) for e in instance["edges"]]
    k = instance["k"]
    if k < 0:
        return False
    # iterate subsets up to k
    vertices = list(range(n))
    for r in range(k + 1):
        for subset in itertools.combinations(vertices, r):
            covered = True
            s = set(subset)
            for u, v in edges:
                if u not in s and v not in s:
                    covered = False
                    break
            if covered:
                return True
    return False


def random_three_sat(max_vars=4, max_clauses=5):
    m = random.randint(0, max_vars)
    # ensure at least 3 vars if there are clauses
    if m < 3:
        # we can still have zero clauses
        pass
    # generate random number of clauses
    c = random.randint(0, max_clauses)
    clauses = []
    for _ in range(c):
        # pick 3 distinct variables from 1..m (if m==0, skip)
        if m == 0:
            break
        vars_ = random.sample(range(1, m + 1), 3)
        clause = []
        for v in vars_:
            lit = v if random.choice([True, False]) else -v
            clause.append(lit)
        clauses.append(clause)
    return {"num_vars": m, "clauses": clauses}


def run_tests(num_tests=200):
    passed = 0
    for i in range(num_tests):
        inst = random_three_sat()
        # validate source
        ThreeSat.validate(inst)
        src_ans = three_sat_bruteforce(inst)
        red = reduce(inst)
        VertexCover.validate(red)
        tgt_ans = vertex_cover_bruteforce(red)
        if src_ans == tgt_ans:
            passed += 1
        else:
            print("Mismatch on instance", json.dumps(inst))
            print("Reduced", red)
            print("src", src_ans, "tgt", tgt_ans)
            break
    return passed, num_tests

if __name__ == "__main__":
    passed, total = run_tests()
    result = {
        "verified": passed == total,
        "tests_run": total,
        "tests_passed": passed,
    }
    print(json.dumps(result))
    with open("verdict.json", "w") as f:
        json.dump(result, f)
EOF"}

